<?php
declare(strict_types=1);$pdo=null;$trips=[];$manifest=[];$error='';if(is_file(__DIR__.'/config.local.php')){require __DIR__.'/config.local.php';try{$pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$trips=$pdo->query("SELECT t.id,CONCAT(o.city,' → ',d.city,' · ',DATE_FORMAT(t.departure_at,'%d/%m %H:%i')) label FROM trips t JOIN routes r ON r.id=t.route_id JOIN terminals o ON o.id=r.origin_id JOIN terminals d ON d.id=r.destination_id WHERE t.status IN ('programado','en curso') ORDER BY t.departure_at LIMIT 50")->fetchAll();$id=(int)($_GET['trip']??($trips[0]['id']??0));if($id){$q=$pdo->prepare("SELECT tk.id,tk.qr_code,tk.status,p.full_name,p.dni,ts.label seat,ts.deck_level FROM tickets tk JOIN passengers p ON p.id=tk.passenger_id JOIN trip_seats ts ON ts.id=tk.trip_seat_id WHERE tk.trip_id=? ORDER BY ts.deck_level,ts.label");$q->execute([$id]);$manifest=$q->fetchAll();}}catch(Throwable $e){$error='Configura la base de datos para consultar el manifiesto.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){$code=trim((string)($_POST['code']??''));$tripId=(int)($_POST['trip']??0);$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,status FROM tickets WHERE qr_code=? AND trip_id=? FOR UPDATE');$q->execute([$code,$tripId]);$ticket=$q->fetch();if($ticket&&$ticket['status']==='valid'){$pdo->prepare("UPDATE tickets SET status='boarded' WHERE id=? AND status='valid'")->execute([$ticket['id']]);if($q->rowCount()===0){$pdo->rollBack();header('Location: manifiesto.php?trip='.$tripId.'&err=1');exit;}$pdo->prepare('INSERT IGNORE INTO boarding_events(ticket_id) VALUES(?)')->execute([$ticket['id']]);$pdo->commit();header('Location: manifiesto.php?trip='.$tripId.'&ok=1');exit;}$pdo->rollBack();header('Location: manifiesto.php?trip='.$tripId.'&err=1');exit;}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Embarque · Ruta Norte</title><link rel="stylesheet" href="assets/app.css?v=20261028"></head><body><header class="top"><a class="brand" href="index.php"><span class="brand-icon">RN</span> RUTA<span>NORTE</span></a><nav><a href="index.php">Buscar viajes</a><a class="active" href="manifiesto.php">Embarque</a><a href="reportes.php">Reportes</a><a href="pasajeros.php">Pasajeros</a></nav><div class="user"><span class="avatar">JV</span><span>Control de viaje<small>Embarque</small></span></div></header><main class="subpage"><div class="eyebrow">OPERACIONES · CONTROL DE SALIDA</div><h1>Embarque de pasajeros</h1><p class="muted">Valida el código QR o ingrésalo manualmente para registrar el abordaje.</p><form class="search-card scan" method="post"><label>VIAJE<select name="trip" onchange="location.href='?trip='+this.value"><?php foreach($trips as $t):?><option value="<?=$t['id']?>" <?=((int)($_GET['trip']??($trips[0]['id']??0))===(int)$t['id']?'selected':'')?>><?=htmlspecialchars($t['label'])?></option><?php endforeach;?></select></label><label>CÓDIGO DEL BOLETO<input name="code" required placeholder="Escanea o escribe el código QR"></label><button class="search-btn">Validar embarque</button></form><?php if(isset($_GET['ok'])):?><div class="notice success">Embarque registrado correctamente.</div><?php elseif(isset($_GET['err'])):?><div class="notice">Boleto inválido, cancelado o ya utilizado.</div><?php endif;?><?php if($error):?><div class="notice"><?=$error?></div><?php endif;?><div class="section-head"><div><div class="eyebrow">LISTA DE PASAJEROS</div><h2>Manifiesto <span><?=count($manifest)?></span></h2></div><button class="outline" onclick="window.print()">Imprimir manifiesto</button></div><div class="manifest"><div class="manifest-row manifest-title"><span>Pasajero</span><span>DNI</span><span>Asiento</span><span>Piso</span><span>Estado</span><span>Código</span></div><?php foreach($manifest as $p):?><div class="manifest-row"><b><?=htmlspecialchars($p['full_name'])?></b><span><?=htmlspecialchars($p['dni'])?></span><span><?=htmlspecialchars($p['seat'])?></span><span><?=htmlspecialchars((string)$p['deck_level'])?></span><span class="status <?=htmlspecialchars($p['status'])?>"><?=htmlspecialchars($p['status']==='boarded'?'Abordó':'Pendiente')?></span><code><?=htmlspecialchars(substr($p['qr_code'],0,10))?>…</code></div><?php endforeach;?><?php if(!$manifest):?><div class="empty">Este viaje todavía no tiene boletos vendidos.</div><?php endif;?></div></main></body></html>
